### 🔧 C
- **`getopt` / `getopt_long`** (POSIX standard)
```c
#include <stdio.h>
#include <getopt.h>
int main(int argc, char *argv[]) {
    int opt;
    char *name = NULL;
    int count = 1;
    while ((opt = getopt_long(argc, argv, "n:c:", NULL, NULL)) != -1) {
        switch (opt) {
            case 'n': name = optarg; break;
            case 'c': count = atoi(optarg); break;
        }
    }
    printf("Hello %s! Count: %d\n", name, count);
    return 0;
}
```

